\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\DeclareMathOperator{\PF}{PF}
\DeclareMathOperator{\ord}{ord}
\newcommand{\ld}{\lambda\text{-}\mathrm{diff}}
\newcommand{\ldm}{\lambda\text{-}\mathrm{diff}_\mu}

\title{An Arithmetic Model for the $\mu$-Extension of Matsuno's Sharp/Flat $\lambda$-Difference Formula}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\begin{abstract}
Let $E$ be an elliptic curve over $\mathbb{Q}$ with good supersingular reduction at the prime $2$, and let $D$ be a square-free integer with $D \equiv 1 \pmod 4$. When the relevant $2$-adic $\mu$-invariant vanishes, a formula of Matsuno expresses the difference $\lambda^\sharp - \lambda^\flat$ of the Kobayashi--Sprung sharp and flat Iwasawa $\lambda$-invariants of the quadratic twist $E^D$ as a local sum over the primes dividing $D$, each weighted by a power of two determined by a $2$-adic depth. We study, in an explicit and deliberately contrarian arithmetic model, the case of a non-vanishing $\mu$-invariant. We posit
\[
\ldm(D) = \ld(D) + \mu \cdot \sum_{\ell \mid D} 2^{n_\ell}, \qquad n_\ell = v_2\!\left(\tfrac{\ell^2-1}{8}\right),
\]
and establish: complete additivity over coprime moduli; an exact inversion formula recovering $\mu$ from the twist data whenever $D$ is ramified; strict monotonicity and injectivity in $\mu$; strict growth under adjoining a ramified prime; and a $2$-adic depth law $8\cdot 2^{n_\ell} = 2^{v_2(\ell-1)+v_2(\ell+1)}$. We also refute three plausible conjectures with explicit counterexamples: the invariant is additive but not multiplicative; recovery of $\mu$ requires a prime divisor of $D$; and the $\mu$-correction is not lower-order --- it can strictly exceed the entire classical contribution.
\end{abstract}

\maketitle

\section{Introduction}

Iwasawa theory studies arithmetic invariants of a $p$-adic Galois module along the cyclotomic $\mathbb{Z}_p$-extension. For an elliptic curve $E/\mathbb{Q}$ at a prime $p$ of good ordinary reduction, the $p$-primary Selmer group over the tower is a cofinitely generated cotorsion module over the Iwasawa algebra $\Lambda = \mathbb{Z}_p[[T]]$, with an associated $\mu$-invariant and $\lambda$-invariant. In the supersingular case the naive Selmer group fails to be cotorsion, and one uses the plus/minus (Kobayashi) or sharp/flat (Kobayashi--Sprung) Selmer groups, producing two $\lambda$-invariants $\lambda^\sharp, \lambda^\flat$.

Matsuno's formula describes the difference $\lambda^\sharp(E^D) - \lambda^\flat(E^D)$ for a quadratic twist $E^D$ by a square-free $D \equiv 1 \pmod 4$, under the assumption that the pertinent $\mu$-invariant vanishes: it is a sum of local terms indexed by the primes $\ell \mid D$, controlled by the $2$-adic depth $n_\ell = v_2((\ell^2-1)/8)$.

The vanishing of $\mu$ is a genuine hypothesis. This paper asks: \emph{when $\mu \neq 0$, how is Matsuno's formula corrected?} We formalize the natural expectation --- a correction proportional to $\mu$, with local weight matching the classical depth --- as an explicit arithmetic model and interrogate it in a contrarian manner, proving structural theorems and refuting plausible-but-false conjectures.

\section{Definitions}

Let $v_2 \colon \mathbb{N} \to \mathbb{N}$ be the $2$-adic valuation, and for $D \in \mathbb{N}$ write $\PF(D)$ for the set of prime divisors of $D$.

\begin{definition}[$2$-adic depth]
For $\ell \in \mathbb{N}$, set $n_\ell = v_2\!\left(\frac{\ell^2-1}{8}\right)$. For odd $\ell$, $8 \mid \ell^2-1$, so $n_\ell = v_2(\ell^2-1) - 3$.
\end{definition}

\begin{definition}[Classical local term]
Given a conductor datum $N_E \in \mathbb{N}$ and reduction-order function $\ord \colon \mathbb{N}\to\mathbb{N}$,
\[
c_\ell = \begin{cases}
2^{n_\ell} & \ell \mid N_E,\\
2^{n_\ell+1} & \ell \nmid N_E,\ 2 \mid \ord(\ell),\\
0 & \text{otherwise.}
\end{cases}
\]
\end{definition}

\begin{definition}[Classical $\lambda$-difference]
$\ld(D) = \sum_{\ell \in \PF(D)} c_\ell.$
\end{definition}

\begin{definition}[$\mu$-weight and total weight]
$w_\ell = 2^{n_\ell}$, and $W(D) = \sum_{\ell \in \PF(D)} 2^{n_\ell}.$
\end{definition}

\begin{definition}[Corrected invariant]
$\ldm(D) = \ld(D) + \mu \cdot W(D).$
\end{definition}

\section{Elementary positivity}

\begin{lemma}
For every $\ell$, $w_\ell = 2^{n_\ell} > 0$.
\end{lemma}

\begin{lemma}
$W(D) > 0$ iff $\PF(D) \neq \varnothing$.
\end{lemma}
\begin{proof}
The empty sum is $0$; a nonempty sum of positive terms is positive.
\end{proof}

\begin{lemma}
If $p$ is prime, $W(p) = 2^{n_p}$.
\end{lemma}

\section{Additivity}

\begin{lemma}
If $\gcd(a,b)=1$ with $a,b\neq 0$ then $\PF(ab) = \PF(a) \sqcup \PF(b)$.
\end{lemma}

\begin{theorem}
For coprime $a,b\neq 0$: $\ld(ab)=\ld(a)+\ld(b)$ and $W(ab)=W(a)+W(b)$.
\end{theorem}
\begin{proof}
Each is a sum over $\PF(\cdot)$ of a function of $\ell$; the index set splits disjointly.
\end{proof}

\begin{theorem}[Complete additivity]
For coprime $a,b\neq 0$ and any $N_E,\mu,\ord$, $\ldm(ab)=\ldm(a)+\ldm(b)$.
\end{theorem}
\begin{proof}
Expand $\ldm = \ld + \mu W$ and apply the previous theorem to each summand.
\end{proof}

\section{The $\mu$-contribution and its inversion}

\begin{theorem}
$\lambda\text{-}\mathrm{diff}_0(D) = \ld(D)$.
\end{theorem}

\begin{theorem}
$\ldm(D) - \ld(D) = \mu \cdot W(D)$.
\end{theorem}

\begin{theorem}[Inversion / exact recovery of $\mu$]
If $\PF(D) \neq \varnothing$ then $\dfrac{\ldm(D)-\ld(D)}{W(D)} = \mu.$
\end{theorem}
\begin{proof}
The numerator is $\mu W(D)$; the ramification hypothesis gives $W(D) > 0$, so the ratio is $\mu$.
\end{proof}

\section{Monotonicity, injectivity, growth}

\begin{theorem}
If $\PF(D)\neq\varnothing$, then $\mu \mapsto \ldm(D)$ is strictly increasing.
\end{theorem}
\begin{proof}
For $a<b$, $a\,W(D) < b\,W(D)$ since $W(D)>0$; add the common term $\ld(D)$.
\end{proof}

\begin{theorem}
If $\PF(D)\neq\varnothing$, then $\mu\mapsto\ldm(D)$ is injective.
\end{theorem}

\begin{theorem}[Growth under a new ramified prime]
If $p$ is prime, $p\nmid D$, $D\neq 0$, $\mu>0$, then $\ldm(D) < \ldm(pD)$.
\end{theorem}
\begin{proof}
By coprimality $\ldm(pD)=\ldm(p)+\ldm(D)$, and $\ldm(p) = \ld(p) + \mu\,2^{n_p} > 0$.
\end{proof}

\section{The $2$-adic depth law}

\begin{lemma}
For odd $\ell$, $8 \mid \ell^2-1$.
\end{lemma}
\begin{proof}
$\ell^2-1=(\ell-1)(\ell+1)$ is a product of consecutive evens.
\end{proof}

\begin{lemma}
For odd $\ell\geq3$, $v_2(\ell^2-1) = n_\ell+3$ and $n_\ell+3 = v_2(\ell-1)+v_2(\ell+1)$.
\end{lemma}

\begin{theorem}[Depth law]
For odd $\ell\geq3$, $8\cdot 2^{n_\ell} = 2^{\,v_2(\ell-1)+v_2(\ell+1)}.$
\end{theorem}

\begin{corollary}
$w_\ell = 1$ exactly when $\ell \equiv \pm 3 \pmod 8$.
\end{corollary}

\section{Disproofs}

\begin{theorem}[Multiplicativity fails]
There exist coprime $a,b\neq 0$ and parameters with $\ldm(ab) \neq \ldm(a)\cdot\ldm(b)$.
\end{theorem}
\begin{proof}
Take $a=3,b=5,N_E=1,\mu=0$, $\ord(5)=2$, else $\ord=1$. Then $\ldm(3)=0$, $\ldm(5)>0$, product $0$, but $\ldm(15)=\ldm(3)+\ldm(5)>0$.
\end{proof}

\begin{theorem}[Recovery requires a prime divisor]
For $D=1$, $\mu\mapsto\ldm(1)$ is not injective.
\end{theorem}
\begin{proof}
$W(1)=0$, so $\ldm(1)=\ld(1)$ for all $\mu$; $\mu=0$ and $\mu=1$ collide.
\end{proof}

\begin{theorem}[Not lower-order]
There exist $D,N_E,\mu,\ord$ with $\ld(D) < \mu\,W(D)$.
\end{theorem}
\begin{proof}
Take $D=3,N_E=1,\mu=1,\ord\equiv1$: then $\ld(3)=0 < 2^{n_3} = \mu W(3)$.
\end{proof}

\section{Discussion and future directions}

The inversion theorem reframes the central analytic question --- the true proportionality constant of the $\mu$-correction --- as a single measurable ratio, predicting $C(D) = W(D) = \sum_{\ell\mid D} 2^{n_\ell}$. Additivity constrains any correct correction to be local. The disproofs warn against a multiplicative model, identify exactly when the invariant is blind to $\mu$, and show the $\mu$-term cannot be treated as lower-order.

Future work includes constructing genuine Kobayashi--Sprung sharp/flat Selmer invariants so that $\ld$, $w_\ell$, and $\ldm$ are derived rather than posited; determining the true proportionality constant via the inversion ratio; sharpening the weight law into a congruence-indexed formula tracking $\ell \bmod 8$; and extending injectivity and inversion to layered towers and higher $\mu$.

