from typing import Callable, List

def v2(m: int) -> int:
    """2-adic valuation of a positive integer."""
    k = 0
    while m % 2 == 0:
        m //= 2
        k += 1
    return k

def prime_factors(n: int) -> List[int]:
    """Distinct prime divisors of n."""
    f, d, m = [], 2, n
    while d * d <= m:
        if m % d == 0:
            f.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        f.append(m)
    return f

def n_ell(ell: int) -> int:
    return v2((ell * ell - 1) // 8)

def mu_weight(ell: int) -> int:
    return 2 ** n_ell(ell)

def weight_sum(D: int) -> int:
    return sum(mu_weight(e) for e in prime_factors(D))

def local_term(NE: int, ord_fn: Callable[[int], int], ell: int) -> int:
    if NE % ell == 0:
        return 2 ** n_ell(ell)
    if ord_fn(ell) % 2 == 0:
        return 2 ** (n_ell(ell) + 1)
    return 0

def lambda_diff(D: int, NE: int, ord_fn: Callable[[int], int]) -> int:
    return sum(local_term(NE, ord_fn, e) for e in prime_factors(D))

def lambda_diff_mu(D: int, NE: int, mu: int, ord_fn: Callable[[int], int]) -> int:
    return lambda_diff(D, NE, ord_fn) + mu * weight_sum(D)

def recover_mu(D: int, NE: int, mu: int, ord_fn: Callable[[int], int]) -> int:
    """Inversion formula: exactly recover mu from the twist data."""
    W = weight_sum(D)
    if W == 0:
        raise ValueError("recovery requires a prime divisor of D")
    return (lambda_diff_mu(D, NE, mu, ord_fn) - lambda_diff(D, NE, ord_fn)) // W

if __name__ == "__main__":
    NE = 21
    ord_fn = lambda e: 2 if e % 3 == 1 else 1
    for D in [5, 13, 65, 1105]:
        for mu in [0, 1, 2, 5, 42]:
            assert recover_mu(D, NE, mu, ord_fn) == mu
        print(f"D={D:>5}  W(D)={weight_sum(D)}  recovered mu exactly for all tested mu")

