from typing import Dict

def two_adic_valuation(m: int) -> int:
    """v2(m): number of times 2 divides the positive integer m."""
    if m <= 0:
        raise ValueError("requires positive integer")
    k = 0
    while m % 2 == 0:
        m //= 2
        k += 1
    return k

def depth_and_weight(ell: int) -> Dict[str, int]:
    """Return the 2-adic depth n_ell and the mu-weight w_ell for odd ell >= 3."""
    if ell % 2 == 0 or ell < 3:
        raise ValueError("ell must be odd and >= 3")
    q = (ell * ell - 1) // 8            # exact: 8 | ell^2 - 1 for odd ell
    n = two_adic_valuation(q)
    return {"n_ell": n, "w_ell": 2 ** n}

