def corrected_invariant(D: int, NE: int, mu: int,
                        ord_fn: Callable[[int], int]) -> int:
    """Compute lambda_diff_mu(D) = classical Matsuno term + mu * W(D)."""
    classical = 0
    weight = 0
    for ell in prime_factors(D):
        n = two_adic_valuation((ell * ell - 1) // 8)
        w = 2 ** n
        weight += w
        if NE % ell == 0:
            classical += w
        elif ord_fn(ell) % 2 == 0:
            classical += 2 * w
        # else contributes 0
    return classical + mu * weight

