def prime_factors(n: int) -> List[int]:
    f, d, m = [], 2, n
    while d * d <= m:
        if m % d == 0:
            f.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        f.append(m)
    return f

def two_adic_valuation(m: int) -> int:
    k = 0
    while m % 2 == 0:
        m //= 2
        k += 1
    return k

def weight_sum(D: int) -> int:
    return sum(2 ** two_adic_valuation((e * e - 1) // 8) for e in prime_factors(D))

def invert_mu(lambda_diff_mu_val: int, lambda_diff_val: int, D: int) -> int:
    """Recover mu exactly from observed twist data. Requires W(D) > 0."""
    W = weight_sum(D)
    if W == 0:
        raise ValueError("D has no prime divisor; mu is not recoverable")
    excess = lambda_diff_mu_val - lambda_diff_val
    if excess % W != 0:
        raise ValueError("data inconsistent with the linear-in-mu model")
    return excess // W

