"""Plot lambda_diff_mu(D) as a function of mu for several ramified D,
illustrating strict monotonicity (slope = W(D)) and injectivity."""
import matplotlib.pyplot as plt

def v2(m: int) -> int:
    k = 0
    while m % 2 == 0:
        m //= 2; k += 1
    return k

def prime_factors(n: int):
    f, d, m = [], 2, n
    while d * d <= m:
        if m % d == 0:
            f.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        f.append(m)
    return f

def weight_sum(D):
    return sum(2 ** v2((e * e - 1) // 8) for e in prime_factors(D))

mus = list(range(0, 11))
plt.figure(figsize=(9, 6))
for D in [5, 15, 105, 1155]:
    W = weight_sum(D)
    ys = [0 + mu * W for mu in mus]  # classical term taken 0 for clarity
    plt.plot(mus, ys, marker="o", label=f"D={D}  (slope W(D)={W})")
plt.xlabel("mu"); plt.ylabel("lambda_diff_mu(D) - lambda_diff(D)")
plt.title("Strict monotonicity in mu: slope equals the total weight W(D)")
plt.legend(); plt.grid(True, alpha=0.3)
plt.tight_layout(); plt.savefig("monotone.png", dpi=130)
